import redis from 'redis';

const redisClient = redis.createClient({
  host: 'localhost',
  port: 6379
});

redisClient.on('error', (err) => {
  console.error('Redis client error:', err);
});

redisClient.on('ready', () => {
  console.log('Redis client ready');
});

redisClient.on('end', () => {
  console.log('Redis client disconnected');
});

// Función para obtener datos de Redis
async function getFromRedis(key: string) {
  return new Promise<string>((resolve, reject) => {
    redisClient.get(key, (err, data) => {
      if (err) {
        return reject(err);
      }
      resolve(data);
    });
  });
}

// Función para almacenar datos en Redis
async function setToRedis(key: string, value: string) {
  return new Promise<void>((resolve, reject) => {
    redisClient.set(key, value, (err) => {
      if (err) {
        return reject(err);
      }
      resolve();
    });
  });
}

// Utilización de las funciones de Redis
(async () => {
  const key = 'exampleKey';
  const value = 'exampleValue';

  // Obtener datos de Redis
  const data = await getFromRedis(key);
  console.log(data); // Salida: exampleValue

  // Almacenar datos en Redis
  await setToRedis(key, value);
  console.log('Data has been set in Redis'); // Salida: Data has been set in Redis
})();
