```tsx
import React, { useState, useEffect } from 'react';

const ProductList = ({ products }) => {
  const [filteredProducts, setFilteredProducts] = useState([]);

  useEffect(() => {
    setFilteredProducts(products);
  }, [products]);

  return (
    <ul>
