### Mejora de rendimiento (Optimización):

Si la API siempre devuelve un objeto JSON que contiene un array de objetos `User`, podemos mejorar la eficiencia añadiendo una línea de código adicional para convertir directamente el array de objetos en un array de `User`:

```typescript
import { User } from './user.model';

export const getUsers = async (): Promise<User[]> => {
    const response = await fetch('https://api.example.com/users');
    const data = await response.json();

    if (!response.ok) {
        throw new Error(`Error fetching users: ${response.statusText}`);
    }

    // Convertir el array de objetos en un array de User
    const users: User[] = data.map((user: any) => {
        return new User(user.id, user.name, user.email, user.role);
    });

    return users;
};
```

