    const productId = '456';
    const quantity = 10;

    // Simulamos la respuesta de la API de actualización de stock
    const mockUpdateStockResponse = { id: productId, stock: quantity };

    // Simulamos que la actualización de stock fallo
    jest.spyOn(inventoryService, 'updateStock').mockRejectedValue(new Error('Product not found'));

    // Ejecutamos la función para actualizar el stock
