  const response = await axios.get('https://api.example.com/todos');
  return response.data;
};

// Creamos una función que se encargará de hacer la llamada a la API y devolverá el resultado
const useFetchTodos = () => {
  return useQuery('todos', fetchTodos);
};

// Importamos el componente de React que usaremos en la aplicación
