```typescript
// Supongamos que tenemos una función que realiza una operación de búsqueda en una base de datos
function buscarDatosEnBD(query: string): Promise<any> {
    return new Promise((resolve, reject) => {
        setTimeout(() => {
            const datos = obtenerDatosDesdeBD(query);
            resolve(datos);
        }, 1000); // Simulación de tiempo de ejecución
    });
}

// Mejora de rendimiento: 
// Siempre que se repita una operación de búsqueda, la base de datos puede ser la misma.
// Podemos almacenar la promesa de la búsqueda para evitar la repetición de la operación.
// Además, si la búsqueda no ha ocurrido, podemos reutilizar la promesa.

const searchCache: { [key: string]: Promise<any> } = {};

function buscarDatosEnBD(query: string): Promise<any> {
    if (!searchCache[query]) {
        searchCache[query] = new Promise((resolve, reject) => {
            setTimeout(() => {
                const datos = obtenerDatosDesdeBD(query);
                resolve(datos);
            }, 1000); // Simulación de tiempo de ejecución
        });
    }
    return searchCache[query];
}
```

En este ejemplo, hemos optimizado la función `buscarDatosEnBD` para evitar la repetición de la operación de búsqueda en la base de datos. Esto puede mejorar significativamente el rendimiento si la misma búsqueda se realiza con frecuencia.

