```typescript
import * as dotenv from 'dotenv';
import * as mqtt from 'mqtt';
import * as fs from 'fs';

dotenv.config();

const client = mqtt.connect(process.env.MQTT_HOST);

client.on('connect', () => {
    client.subscribe(process.env.MQTT_TOPIC);
});

client.on('message', (topic, message) => {
