### Ejemplo de Componente React que maneja datos de una API

```typescript
import React, { useState, useEffect } from 'react';

const DataFetcher = () => {
  const [data, setData] = useState<any[]>([]);
  const [loading, setLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      setError(null);
      try {
        const response = await fetch('https://api.example.com/data');
        const result = await response.json();
        setData(result);
      } catch (error) {
        setError(error.message);
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  return (
    <div>
      {loading && <p>Loading...</p>}
      {error && <p>Error: {error}</p>}
      {!loading && !error && data.length > 0 && (
        <ul>
          {data.map((item: any) => (
            <li key={item.id}>{item.name}</li>
          ))}
        </ul>
      )}
    </div>
  );
};

export default DataFetcher;
```

### Mejora de Rendimiento: Evitar la Repeticion de Fetch

En este ejemplo, estamos utilizando `useEffect` para hacer una solicitud a una API y manejar los datos. Sin embargo, si el componente se actualiza y la URL de la API no cambia, la solicitud se repite. Esto puede ser ineficiente si la URL no cambia.

Para evitar esto, podemos utilizar `useMemo` para evitar la repetición de la solicitud a la API.

### Mejora de Rendimiento con useMemo

```typescript
import React, { useState, useEffect, useMemo } from 'react';

const DataFetcher = () => {
  const [data, setData] = useState<any[]>([]);
  const [loading, setLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);

  const fetchData = async () => {
    setLoading(true);
    setError(null);
    try {
      const response = await fetch('https://api.example.com/data');
      const result = await response.json();
      setData(result);
    } catch (error) {
      setError(error.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  const cachedFetchData = useMemo(() => {
    if (!loading && !error && data.length === 0) {
      fetchData();
    }
    return data;
  }, [loading, error, data]);

  return (
    <div>
      {loading && <p>Loading...</p>}
      {error && <p>Error: {error}</p>}
      {!loading && !error && cachedFetchData.length > 0 && (
        <ul>
          {cachedFetchData.map((item: any) => (
            <li key={item.id}>{item.name}</li>
