```typescript
// Supongamos que tenemos un componente llamado AverageCalculator que recibe un array de números y muestra el promedio.
import React, { useState } from 'react';

const AverageCalculator = ({ numbers }) => {
  const [average, setAverage] = useState<number | null>(null);

  const calculateAverage = () => {
    if (numbers.length > 0) {
      const sum = numbers.reduce((acc, num) => acc + num, 0);
      const average = sum / numbers.length;
      setAverage(average);
    } else {
      setAverage(null);
    }
  };

  return (
    <div>
      <button onClick={calculateAverage}>Calcular Promedio</button>
      {average !== null && <p>El promedio es: {average}</p>}
    </div>
  );
};

export default AverageCalculator;
```

#### Nuevo Caso de Prueba

Ahora, vamos a crear un nuevo test para este componente que asegure que el promedio se calcula correctamente cuando se ingresan números válidos y que el promedio se establece en `null` cuando se ingresan números vacíos o nulos.

```typescript
