import AverageCalculator from './AverageCalculator';

describe('AverageCalculator', () => {
  test('calcula el promedio correctamente', () => {
    const numbers = [1, 2, 3, 4, 5];
    render(<AverageCalculator numbers={numbers} />);
    const button = screen.getByText('Calcular Promedio');
    fireEvent.click(button);
    expect(screen.getByText('El promedio es: 3')).toBeInTheDocument();
  });

  test('calcula el promedio correctamente con números vacíos', () => {
    const numbers = [];
    render(<AverageCalculator numbers={numbers} />);
    const button = screen.getByText('Calcular Promedio');
    fireEvent.click(button);
    expect(screen.getByText('El promedio es: null')).toBeInTheDocument();
  });

  test('no calcula el promedio cuando no se ingresan números', () => {
    const numbers = undefined;
    render(<AverageCalculator numbers={numbers} />);
    const button = screen.getByText('Calcular Promedio');
    fireEvent.click(button);
    expect(screen.queryByText('El promedio es:')).toBeNull();
  });
});
```

Estos tests aseguran que el componente `AverageCalculator` está funcionando correctamente en diferentes escenarios. El primero verifica que el promedio se calcula correctamente con una lista de números, el segundo verifica que el promedio se establece en `null` cuando no se proporciona una lista de números, y el tercero verifica que no se calcula el promedio cuando no se proporciona una lista de números.

