const connection = mysql.createConnection({
  host: 'your_host',
  user: 'your_user',
  password: 'your_password',
  database: 'your_database'
});

// Función para obtener los datos de manera eficiente
function getUsers() {
  return new Promise((resolve, reject) => {
    const query = 'SELECT * FROM users WHERE status = ? LIMIT ?, ?';
    connection.query(query, ['active', 100, 100], (err, results) => {
      if (err) {
        reject(err);
      } else {
        resolve(results);
      }
    });
  });
}

