// Obtener productos de la base de datos local
function obtenerProductosEnLocal(ids) {
    const productos = new Map();
    for (const id of ids) {
        const producto = localStorage.getItem(`producto_${id}`);
        if (producto) {
            productos.set(id, JSON.parse(producto));
        }
    }
    return productos;
}

