```typescript
import React, { memo, useMemo } from 'react';

// Supongamos que tenemos una función que retorna un componente
const MyComponent = memo(({ data }) => {
  // Aquí está una función que podría causar renderizaciones innecesarias
  const renderData = () => {
    // Aquí está el código que podría ser optimizado
    return (
      <div>
