const MyComponent = () => {
  const { component, location, match } = useCachedRoute('/my-route');

  if (!component) return null;

  return <component location={location} match={match} />;
};
```

3. **Uso de Caches en Componentes de Estado**: Utilizar caches para componentes de estado para evitar la recarga innecesaria de componentes basados en estado.

```typescript
import { useCachedRoute } from './useCachedRoute';

const MyStateComponent = () => {
  const { component, location, match } = useCachedRoute('/my-state-route');

  if (!component) return null;

  const [state, setState] = useState(initialState);

  useEffect(() => {
    // Aquí puedes realizar acciones de estado basadas en la ruta
  }, [match]);

  return <component location={location} match={match} state={state} setState={setState} />;
};
```

