```typescript
// lazyLoadImage.ts
import React from 'react';

function lazyLoadImage(Component: React.ComponentType) {
  const LazyComponent = React.lazy(() => import(Component));
  return React.forwardRef((props, ref) => (
    <LazyComponent ref={ref} {...props} />
  ));
}

export default lazyLoadImage;
```

Con estos cambios, la imagen se cargará solo cuando se vea, lo que puede mejorar significativamente el tiempo de carga del sitio web.

